#!/bin/sh
# The acceptance oracle for `tail_last` in src/tally.sh.
#
# FOUR cases, of which TWO pass on the unfixed tree and TWO fail. That ratio is
# deliberate: a suite that is entirely red proves only that something is broken,
# while a suite that is mostly green with two named failures tells an agent
# exactly what to fix and leaves a signal that the fix did not break the rest.
#
# DO NOT EDIT THIS FILE to make the suite pass. It is the acceptance contract;
# the change belongs in `src/tally.sh`.
#
# Emits one `ok`/`FAIL` line per case, then `Ran N tests` and `failures=N` —
# the keys `tests/check.sh` parses. Exit 0 when nothing failed, 1 otherwise.

set -u
# Source the subject relative to this file, so the suite runs from any cwd —
# `check.sh` extracts a commit's archive into a scratch dir and runs there.
. "$(dirname "$0")/../src/tally.sh"

ran=0
passed=0
failed=0

expect() {
    name=$1
    want=$2
    shift 2
    ran=$((ran + 1))
    if got=$(tail_last "$@" 2>/dev/null); then
        :
    else
        got="__tail_last refused: rc=$?__"
    fi
    if [ "$got" = "$want" ]; then
        passed=$((passed + 1))
        printf 'ok %s\n' "$name"
    else
        failed=$((failed + 1))
        printf 'FAIL %s\n  wanted: [%s]\n  got:    [%s]\n' "$name" "$want" "$got"
    fi
}

# PASSES on the unfixed tree — the ordinary case is not the defect.
expect returns_the_last_n_when_n_is_smaller "$(printf '2\n3')" 2 1 2 3
# PASSES on the unfixed tree.
expect zero_returns_empty "" 0 1 2 3
# RED on the unfixed tree: `count - n` goes negative, and the refusal fires
# where the contract promises everything.
expect n_larger_than_the_list_returns_everything "$(printf '1\n2\n3')" 9 1 2 3
# RED on the unfixed tree, for the same negative-start reason.
expect empty_list_returns_empty "" 4

printf 'Ran %s tests\n' "$ran"
printf 'failures=%s\n' "$failed"
[ "$failed" -eq 0 ]
